.dwb-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.dwb-root,.dwb-root *,.dwb-root *::before,.dwb-root *::after{box-sizing:border-box}
.dwb-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.dwb-root img{display:block;border:0;max-width:none}
.dwb-root > [data-node-id]{will-change:transform}
.dwb-root [hidden]{display:none!important}
.dwb-root [data-sh-theme="dark"]{display:none!important}
.dwb-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.dwb-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.dwb-root .n1_2663{background-color:var(--wa-bg, #f9f9fc);align-content:stretch;display:flex;gap:8px;height:100%;align-items:center;justify-content:center;padding-bottom:8px;padding-top:2px;padding-left:30px;padding-right:30px;position:relative;border-bottom-left-radius:6px;border-bottom-right-radius:6px;flex-shrink:0}
.dwb-root .n1_2663::after{content:"";position:absolute;inset:0;border:1px solid var(--wa-point, #e2e4f2);border-radius:inherit;border-width:0 1px 1px 1px;pointer-events:none}
.dwb-root .n1_2664{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:16px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #414651);font-size:13px;white-space:nowrap;width:45px}
.dwb-root .n1_2665{display:flex;height:4.94px;align-items:center;justify-content:center;position:relative;flex-shrink:0;width:8px}
.dwb-root .x37{flex:none;transform:rotate(-90deg)}
.dwb-root .x38{height:8px;position:relative;width:4.94px}
.dwb-root .x39{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.dwb-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.dwb-root[data-theme="dark"] [data-name="Header"] > [data-name="Background"]{background:var(--wa-bg, #131519)!important;box-shadow:inset 0 -1px 0 rgba(255,255,255,.06)!important}
.dwb-root[data-theme="dark"] [data-name="Input"],.dwb-root[data-theme="dark"] [data-name="Select"],.dwb-root[data-theme="dark"] [data-name^="Field/ID"],.dwb-root[data-theme="dark"] [data-name^="Field/Password"]{background-color:var(--wa-bg, #111316)}
.dwb-root[data-theme="dark"] [data-name="Widget/Notice"] > div:first-child,.dwb-root[data-theme="dark"] [data-name="Widget/Help Desk"] > div:first-child,.dwb-root[data-theme="dark"] [data-name="Panel"] > div:first-child{background-image:linear-gradient(180deg,color-mix(in srgb, var(--wa-surface, rgb(33 36 43)) 64%, transparent),color-mix(in srgb, var(--wa-bg, rgb(19 21 26)) 76%, transparent))!important;background-color:transparent!important;backdrop-filter:blur(18px) saturate(1.15)!important;-webkit-backdrop-filter:blur(18px) saturate(1.15)!important}
.dwb-root[data-theme="dark"] [data-name="Widget/Notice"] > div:nth-child(3),.dwb-root[data-theme="dark"] [data-name="Widget/Help Desk"] > div:nth-child(3),.dwb-root[data-theme="dark"] [data-name="Panel"] > div:nth-child(3){box-shadow:inset 0 1px 0 rgba(255,255,255,.1),inset 0 0 0 1px rgba(255,255,255,.07),0 24px 48px rgba(0,0,0,.34)!important}
.dwb-root[data-theme="dark"] > [data-node-id]:has([data-name^="Widget/"]) > [data-name="Header"] > [data-name="Background"]{background:color-mix(in srgb, var(--wa-bg, rgb(14 16 20)) 68%, transparent)!important;backdrop-filter:blur(18px)!important;-webkit-backdrop-filter:blur(18px)!important}
.dwb-root[data-theme="dark"] [data-name^="Step/"] > div:first-child{background-color:color-mix(in srgb, var(--wa-point, rgb(130 155 255)) 12%, transparent)}
.dwb-root[data-theme="dark"] [data-name^="Widget/"] [data-name="List Item/Post"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 4.5%, transparent)}
.dwb-root[data-theme="dark"] [data-name="Count"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 10%, transparent)!important}
.dwb-root[data-theme="dark"] [data-name="Login Card"] > div:first-child{background-image:linear-gradient(180deg,color-mix(in srgb, var(--wa-surface, rgb(33 36 43)) 62%, transparent),color-mix(in srgb, var(--wa-bg, rgb(19 21 26)) 74%, transparent))!important;background-color:transparent!important;backdrop-filter:blur(18px)!important;-webkit-backdrop-filter:blur(18px)!important}
.dwb-root[data-theme="dark"] [data-name="Login Card"] > div:nth-child(2){box-shadow:inset 0 1px 0 rgba(255,255,255,.12),inset 0 0 0 1px rgba(255,255,255,.08),0 30px 60px rgba(0,0,0,.4)!important}
.dwb-root[data-theme="dark"] [data-name="Search Overlay"] > [data-name="Background"],.dwb-root[data-theme="dark"] [data-name="Background"][data-node-id="1:6533"]{background-color:var(--wa-surface, #17191e)!important}
.dwb-root[data-theme="dark"] .n1_2663{background-color:var(--wa-surface, #17191e)}
.dwb-root[data-theme="dark"] .n1_2663::after{border-color:var(--wa-line, #31343c)}
.dwb-root[data-theme="dark"] .n1_2664{color:var(--wa-text-sub, #c9cdd6)}
